class ProviderStream:
    """Delegated stream with exactly one best-effort settlement on consumption/close."""

    def __init__(
        self, stream: Any, meter: Meter, transaction: str, snapshot: UsageSnapshot
    ) -> None:
        self._stream = stream
        self._iterator = stream.__iter__()
        self._meter = meter
        self._transaction = transaction
        self._snapshot = snapshot
        self._settled = False

    def __getattr__(self, name: str) -> Any:
        return getattr(self._stream, name)

    def __iter__(self) -> Iterator[Any]:
        return self

    def __next__(self) -> Any:
        try:
            event = self._iterator.__next__()
        except StopIteration:
            self._settle("PROVIDER_ERROR" if self._snapshot.failed else "SUCCESS")
            raise
        except BaseException as error:
            self._settle(request_status_of(error))
            raise
        try:
            self._snapshot.event(event)
        except Exception:
            log.exception("Kaiten AI usage: stream usage extraction failed; keeping known usage")
        if self._snapshot.completed:
            self._settle("PROVIDER_ERROR" if self._snapshot.failed else "SUCCESS")
        return event

    def _settle(self, status: AiRequestStatus) -> None:
        if not self._settled:
            self._settled = True
            self._meter.commit(self._transaction, request_status=status, usage=self._snapshot.usage)

    def close(self) -> None:
        try:
            self._stream.close()
        finally:
            status: AiRequestStatus = (
                "SUCCESS"
                if self._snapshot.completed
                else "CUSTOMER_ERROR"
                if self._snapshot.received
                else "NOT_SENT"
            )
            self._settle(status)

    def __enter__(self) -> ProviderStream:
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        traceback: TracebackType | None,
    ) -> None:
        self.close()

    @property
    def text_stream(self) -> Iterator[str]:
        def texts() -> Iterator[str]:
            for event in self:
                kind = get(event, "type")
                delta = get(event, "delta")
                if kind == "text":
                    yield get(event, "text", "")
                elif (
                    self._snapshot.operation != "messages.stream"
                    and kind == "content_block_delta"
                    and get(delta, "type") == "text_delta"
                ):
                    yield get(delta, "text", "")

        return texts()

    def until_done(self) -> None:
        for _ in self:
            pass

    def get_final_message(self) -> Any:
        self.until_done()
        return self._stream.get_final_message()

    def get_final_text(self) -> str:
        message = self.get_final_message()
        return "".join(get(block, "text", "") for block in get(message, "content", []))


class ProviderStreamManager:
    """Anthropic's stream factory is synchronous, opening the network on async entry."""

    def __init__(
        self, provider: Provider, target: Callable[..., Any], path: str, kwargs: dict[str, Any]
    ) -> None:
        self._provider = provider
        self._target = target
        self._path = path
        self._kwargs = kwargs
        self._manager: Any = None
        self._stream: ProviderStream | None = None

    def __enter__(self) -> Any:
        transaction = self._provider._reserve(self._path, self._kwargs)
        try:
            self._manager = self._target(**self._kwargs)
            stream = self._manager.__enter__()
        except BaseException as error:
            if transaction is not None:
                self._provider._meter.commit(transaction, request_status=request_status_of(error))
            raise
        if transaction is None:
            return stream
        self._stream = ProviderStream(
            stream, self._provider._meter, transaction, UsageSnapshot("anthropic", self._path)
        )
        return self._stream

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        traceback: TracebackType | None,
    ) -> Any:
        try:
            return self._manager.__exit__(exc_type, exc, traceback)
        finally:
            if self._stream is not None:
                self._stream.close()
